Proceso ContarVocales
    Definir Mutable palabra Como Cadena <- "";
    Definir Mutable letra Como Caracter <- "a";
    Leer palabra;
    Definir Mutable contador Como Entero <- 0;
    Para i <- 0 Hasta Longitud(palabra) - 1 Con Paso 1 Hacer
        letra <- CaracterEn(palabra, i);
        Si letra = 'a' O letra = 'e' O letra = 'i' O letra = 'o' O letra = 'u' Entonces
            contador <- contador + 1;
        FinSi
    FinPara
    Escribir contador;
FinProceso
